import { Button } from "@heroui/react";
import { useQuery } from "@tanstack/react-query";
import { useNavigate } from "react-router";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { nameRoutes } from "../../configs/constants";
import { getAppointments } from "../../services/appointmentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import { formatDateLong } from "../../utils/dateFormatter";

const statusColors: Record<string, string> = {
  Pagada: "bg-green-100 text-green-800 border-green-200",
  "Paciente presente": "bg-purple-100 text-purple-800 border-purple-200",
  "En curso": "bg-blue-100 text-blue-800 border-blue-200",
  Completada: "bg-gray-100 text-gray-800 border-gray-200",
  Pendiente: "bg-yellow-100 text-yellow-800 border-yellow-200",
  Cancelada: "bg-red-100 text-red-800 border-red-200",
  "No asisti├│": "bg-orange-100 text-orange-800 border-orange-200",
};

const statusDots: Record<string, string> = {
  Pagada: "bg-green-500",
  "Paciente presente": "bg-purple-500",
  "En curso": "bg-blue-500",
  Completada: "bg-gray-400",
  Pendiente: "bg-yellow-500",
  Cancelada: "bg-red-500",
  "No asisti├│": "bg-orange-500",
};

function StatCard({
  icon,
  label,
  value,
  color,
}: {
  readonly icon: string;
  readonly label: string;
  readonly value: number;
  readonly color: string;
}) {
  return (
    <div
      className={`rounded-xl border p-5 shadow-sm flex items-center gap-4 ${color}`}
    >
      <div className="text-3xl">
        <i className={`bi ${icon}`} />
      </div>
      <div>
        <p className="text-2xl font-bold">{value}</p>
        <p className="text-sm font-medium opacity-80">{label}</p>
      </div>
    </div>
  );
}

function QuickActionButton({
  icon,
  label,
  to,
}: {
  readonly icon: string;
  readonly label: string;
  readonly to: string;
}) {
  const navigate = useNavigate();
  return (
    <button
      className="flex flex-col items-center gap-2 p-4 bg-white dark:bg-gray-900/50 border rounded-xl shadow-sm hover:border-primary/60 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors w-full"
      onClick={() => navigate(to)}
    >
      <i className={`bi ${icon} text-2xl text-primary`} />
      <span className="text-xs font-semibold text-center text-gray-700 dark:text-gray-300">
        {label}
      </span>
    </button>
  );
}

export function AdminDashboardPage() {
  const navigate = useNavigate();

  // Build today's filter
  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);
  const todayEnd = new Date();
  todayEnd.setHours(23, 59, 59, 999);
  const todayFilter = `State:eq:1 AND AppointmentDate:gte:${todayStart.toISOString()} AND AppointmentDate:lte:${todayEnd.toISOString()}`;

  const { data, isLoading } = useQuery({
    queryKey: ["admin-dashboard-appointments", todayStart.toDateString()],
    queryFn: () =>
      getAppointments({
        pageNumber: 1,
        pageSize: 200,
        filters: todayFilter,
        include: "Specialty,Branch,AppointmentStatus,Patient,Doctor",
        includeTotal: false,
      }),
    refetchInterval: 60000, // auto-refresh every 60s
  });

  const appointments: AppointmentResponse[] = data?.success ? data.data : [];

  // KPI calculations
  const total = appointments.length;
  const pagadas = appointments.filter(
    (a) => a.appointmentStatus?.name === "Pagada",
  ).length;
  const enEspera = appointments.filter(
    (a) => a.arrivalTime && a.appointmentStatus?.name !== "Completada",
  ).length;
  const completadas = appointments.filter(
    (a) => a.appointmentStatus?.name === "Completada",
  ).length;

  // Group by status
  const byStatus = appointments.reduce<Record<string, number>>((acc, a) => {
    const name = a.appointmentStatus?.name ?? "Desconocido";
    acc[name] = (acc[name] ?? 0) + 1;
    return acc;
  }, {});

  // Active doctors today (with paid/in-progress/present appointments)
  const activeDoctorMap = new Map<
    number,
    { name: string; branch: string; specialty: string; count: number }
  >();
  appointments.forEach((a) => {
    if (!a.doctorId) return;
    const statusName = a.appointmentStatus?.name ?? "";
    if (statusName === "Cancelada") return;
    if (!activeDoctorMap.has(a.doctorId)) {
      activeDoctorMap.set(a.doctorId, {
        name: a.doctor?.name ?? `M├®dico #${a.doctorId}`,
        branch: a.branch?.name ?? "ÔÇö",
        specialty: a.specialty?.name ?? "ÔÇö",
        count: 0,
      });
    }
    const entry = activeDoctorMap.get(a.doctorId)!;
    entry.count += 1;
  });
  const activeDoctors = Array.from(activeDoctorMap.values()).sort(
    (a, b) => b.count - a.count,
  );

  return (
    <div className="p-4 max-w-6xl mx-auto">
      <div className="flex items-center justify-between mb-2">
        <h1 className="text-2xl font-bold">Panel de Administraci├│n</h1>
        <span className="text-xs text-gray-400">
          <i className="bi bi-arrow-repeat mr-1" />
          Actualizaci├│n autom├ítica cada 60s
        </span>
      </div>
      <p className="text-gray-500 text-sm mb-6">
        Resumen de operaciones del d├¡a ÔÇö{" "}
        {formatDateLong(todayStart.toISOString())}
      </p>

      {isLoading ? <LoadingComponent /> : null}

      {!isLoading && (
        <>
          {/* KPI Cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
            <StatCard
              color="bg-blue-50 text-blue-800 border-blue-200"
              icon="bi-calendar-check"
              label="Citas hoy"
              value={total}
            />
            <StatCard
              color="bg-green-50 text-green-800 border-green-200"
              icon="bi-cash-coin"
              label="Citas Pagadas"
              value={pagadas}
            />
            <StatCard
              color="bg-purple-50 text-purple-800 border-purple-200"
              icon="bi-person-check"
              label="Pacientes en espera"
              value={enEspera}
            />
            <StatCard
              color="bg-gray-50 text-gray-800 border-gray-200"
              icon="bi-check2-circle"
              label="Completadas hoy"
              value={completadas}
            />
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
            {/* Appointments by status */}
            <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-5">
              <h2 className="font-bold mb-4 text-base">Citas por estado</h2>
              {Object.keys(byStatus).length === 0 ? (
                <p className="text-sm text-gray-400 text-center py-6">
                  Sin citas registradas hoy
                </p>
              ) : (
                <div className="space-y-2">
                  {Object.entries(byStatus).map(([status, count]) => {
                    const colorClass =
                      statusColors[status] ??
                      "bg-gray-100 text-gray-800 border-gray-200";
                    const dotClass = statusDots[status] ?? "bg-gray-400";
                    return (
                      <div
                        key={status}
                        className={`flex items-center justify-between rounded-lg px-3 py-2 border ${colorClass}`}
                      >
                        <div className="flex items-center gap-2">
                          <span
                            className={`w-2.5 h-2.5 rounded-full ${dotClass}`}
                          />
                          <span className="text-sm font-medium">{status}</span>
                        </div>
                        <span className="text-lg font-bold">{count}</span>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Active doctors */}
            <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-5">
              <h2 className="font-bold mb-4 text-base">M├®dicos activos hoy</h2>
              {activeDoctors.length === 0 ? (
                <p className="text-sm text-gray-400 text-center py-6">
                  Sin m├®dicos con citas hoy
                </p>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead className="text-gray-500 text-xs uppercase">
                      <tr>
                        <th className="text-left py-1 pb-2">M├®dico</th>
                        <th className="text-left py-1 pb-2">Sede</th>
                        <th className="text-left py-1 pb-2">Especialidad</th>
                        <th className="text-right py-1 pb-2">Citas</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                      {activeDoctors.map((doc, idx) => (
                        <tr
                          key={idx}
                          className="hover:bg-gray-50 dark:hover:bg-gray-700/30"
                        >
                          <td className="py-2 font-medium">{doc.name}</td>
                          <td className="py-2 text-gray-500">{doc.branch}</td>
                          <td className="py-2 text-gray-500">
                            {doc.specialty}
                          </td>
                          <td className="py-2 text-right font-bold">
                            {doc.count}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>

          {/* Quick actions */}
          <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-5">
            <h2 className="font-bold mb-4 text-base">Acciones r├ípidas</h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-7 gap-3">
              <QuickActionButton
                icon="bi-calendar-plus"
                label="Nueva Cita"
                to={nameRoutes.appointmentCreate}
              />
              <QuickActionButton
                icon="bi-door-open"
                label="Recepci├│n"
                to={nameRoutes.reception}
              />
              <QuickActionButton
                icon="bi-cash-coin"
                label="Caja"
                to={nameRoutes.cashier}
              />
              <QuickActionButton
                icon="bi-heart-pulse"
                label="Signos Vitales"
                to={nameRoutes.nurseDashboard}
              />
              <QuickActionButton
                icon="bi-person-badge"
                label="Gesti├│n M├®dicos"
                to={nameRoutes.doctorManagement}
              />
              <QuickActionButton
                icon="bi-arrow-left-right"
                label="Traslados"
                to={nameRoutes.doctorTransfer}
              />
              <QuickActionButton
                icon="bi-diagram-3"
                label="Especialidades por Sede"
                to={nameRoutes.branchSpecialty}
              />
            </div>
          </div>

          {/* Navigate to appointments */}
          <div className="mt-4 flex justify-end">
            <Button
              variant="secondary"
              onPress={() => navigate(nameRoutes.appointment)}
            >
              <i className="bi bi-list-ul mr-2" />
              Ver todas las citas
            </Button>
          </div>
        </>
      )}
    </div>
  );
}

import { Button, Modal, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import type { SingleValue } from "react-select";
import { AsyncButton } from "../../components/button/AsyncButton";
import { CatalogueSelect } from "../../components/select/CatalogueSelect";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { api } from "../../configs/axios/interceptors";
import { useAuth } from "../../hooks/useAuth";
import { getBranches } from "../../services/branchService";
import { getSpecialties } from "../../services/specialtyService";
import { getUsers } from "../../services/userService";
import type { ApiResponse } from "../../types/ApiResponse";
import type { BranchResponse } from "../../types/BranchResponse";
import type { SpecialtyResponse } from "../../types/SpecialtyResponse";
import type { UserRequest } from "../../types/UserRequest";
import type { UserResponse } from "../../types/UserResponse";

interface EditModalState {
  open: boolean;
  doctor: UserResponse | null;
  branchId: number | null;
  specialtyId: number | null;
}

export function DoctorManagementPage() {
  const { userId } = useAuth();
  const queryClient = useQueryClient();

  const [filterBranchId, setFilterBranchId] = useState<number | null>(null);
  const [filterSpecialtyId, setFilterSpecialtyId] = useState<number | null>(
    null,
  );
  const [modal, setModal] = useState<EditModalState>({
    open: false,
    doctor: null,
    branchId: null,
    specialtyId: null,
  });

  // Build filters for doctor list
  const buildFilters = () => {
    let f = "Rol.Name:eq:Medico AND State:eq:1";
    if (filterBranchId) f += ` AND BranchId:eq:${filterBranchId}`;
    if (filterSpecialtyId) f += ` AND SpecialtyId:eq:${filterSpecialtyId}`;
    return f;
  };

  const { data, isLoading } = useQuery({
    queryKey: ["doctors", filterBranchId, filterSpecialtyId],
    queryFn: () =>
      getUsers({
        pageNumber: 1,
        pageSize: 100,
        filters: buildFilters(),
        include: "Rol,Branch,Specialty",
        includeTotal: false,
      }),
  });

  const updateMutation = useMutation({
    mutationFn: (payload: UserRequest) =>
      api.patch<unknown, ApiResponse<UserResponse>, UserRequest>(
        "User",
        payload,
      ),
    onSuccess: (res) => {
      if (res.success) {
        toast.success("Sede/Especialidad actualizada correctamente");
        queryClient.invalidateQueries({ queryKey: ["doctors"] });
        setModal({
          open: false,
          doctor: null,
          branchId: null,
          specialtyId: null,
        });
      } else {
        toast.danger(res.message ?? "Error al actualizar");
      }
    },
    onError: () => toast.danger("Error inesperado al actualizar"),
  });

  const openModal = useCallback((doctor: UserResponse) => {
    setModal({
      open: true,
      doctor,
      branchId: doctor.branchId ?? null,
      specialtyId: doctor.specialtyId ?? null,
    });
  }, []);

  const closeModal = useCallback(() => {
    setModal({ open: false, doctor: null, branchId: null, specialtyId: null });
  }, []);

  const handleSave = useCallback(() => {
    if (!modal.doctor) return;
    updateMutation.mutate({
      id: modal.doctor.id,
      branchId: modal.branchId,
      specialtyId: modal.specialtyId,
      state: 1,
      updatedBy: userId,
    });
  }, [modal, userId, updateMutation]);

  const selectorBranch = useCallback(
    (item: BranchResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const selectorSpecialty = useCallback(
    (item: SpecialtyResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const doctors = data?.success ? data.data : [];

  return (
    <div className="max-w-5xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-1">Gesti├│n de M├®dicos</h1>
      <p className="text-gray-500 text-sm mb-6">
        Asigne o modifique la sede y especialidad de cada m├®dico.
      </p>

      {/* Filtros */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6 p-4 bg-white dark:bg-gray-800 rounded-xl border shadow-sm">
        <CatalogueSelect<BranchResponse>
          defaultValue={null}
          deps="State:eq:1"
          fieldSearch="Name"
          label="Filtrar por sede"
          name="filterBranch"
          placeholder="Todas las sedes"
          queryFn={getBranches}
          selectorFn={selectorBranch}
          onChange={(opt) => {
            const o = opt as SingleValue<{ label: string; value: string }>;
            setFilterBranchId(o?.value ? Number(o.value) : null);
          }}
        />
        <CatalogueSelect<SpecialtyResponse>
          defaultValue={null}
          deps="State:eq:1"
          fieldSearch="Name"
          label="Filtrar por especialidad"
          name="filterSpecialty"
          placeholder="Todas las especialidades"
          queryFn={getSpecialties}
          selectorFn={selectorSpecialty}
          onChange={(opt) => {
            const o = opt as SingleValue<{ label: string; value: string }>;
            setFilterSpecialtyId(o?.value ? Number(o.value) : null);
          }}
        />
      </div>

      {/* Tabla de m├®dicos */}
      {isLoading ? <LoadingComponent /> : null}

      {!isLoading && doctors.length === 0 && (
        <div className="text-center py-16 text-gray-400">
          <i className="bi bi-person-x text-4xl block mb-3" />
          <p>No se encontraron m├®dicos con los filtros aplicados.</p>
        </div>
      )}

      {!isLoading && doctors.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
              <tr>
                <th className="text-left px-4 py-3 font-semibold">Nombre</th>
                <th className="text-left px-4 py-3 font-semibold">
                  Sede actual
                </th>
                <th className="text-left px-4 py-3 font-semibold">
                  Especialidad actual
                </th>
                <th className="text-left px-4 py-3 font-semibold">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {doctors.map((doctor) => (
                <tr
                  key={doctor.id}
                  className="hover:bg-gray-50 dark:hover:bg-gray-700/40"
                >
                  <td className="px-4 py-3 font-medium">{doctor.name}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-400">
                    {doctor.branch?.name ?? (
                      <span className="text-orange-500 italic">
                        Sin asignar
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-400">
                    {doctor.specialty?.name ?? (
                      <span className="text-orange-500 italic">
                        Sin asignar
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-3">
                    <Button
                      size="sm"
                      variant="secondary"
                      onPress={() => openModal(doctor)}
                    >
                      <i className="bi bi-pencil mr-1" />
                      Editar Sede/Especialidad
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal de edici├│n */}
      <Modal isOpen={modal.open} onOpenChange={closeModal}>
        <Modal.Backdrop>
          <Modal.Container>
            <Modal.Dialog className="max-w-lg w-full">
              <Modal.CloseTrigger />
              <Modal.Header>
                <Modal.Heading>
                  Editar Sede y Especialidad ÔÇö {modal.doctor?.name}
                </Modal.Heading>
              </Modal.Header>
              <Modal.Body>
                <div className="flex flex-col gap-4 p-2">
                  <CatalogueSelect<BranchResponse>
                    defaultValue={
                      modal.doctor?.branch
                        ? {
                            label: modal.doctor.branch.name,
                            value: String(modal.doctor.branchId),
                          }
                        : null
                    }
                    deps="State:eq:1"
                    fieldSearch="Name"
                    label="Nueva sede"
                    name="branchId"
                    placeholder="Seleccione una sede"
                    queryFn={getBranches}
                    selectorFn={selectorBranch}
                    onChange={(opt) => {
                      const o = opt as SingleValue<{
                        label: string;
                        value: string;
                      }>;
                      setModal((prev) => ({
                        ...prev,
                        branchId: o?.value ? Number(o.value) : null,
                      }));
                    }}
                  />
                  <CatalogueSelect<SpecialtyResponse>
                    defaultValue={
                      modal.doctor?.specialty
                        ? {
                            label: modal.doctor.specialty.name,
                            value: String(modal.doctor.specialtyId),
                          }
                        : null
                    }
                    deps="State:eq:1"
                    fieldSearch="Name"
                    label="Nueva especialidad"
                    name="specialtyId"
                    placeholder="Seleccione una especialidad"
                    queryFn={getSpecialties}
                    selectorFn={selectorSpecialty}
                    onChange={(opt) => {
                      const o = opt as SingleValue<{
                        label: string;
                        value: string;
                      }>;
                      setModal((prev) => ({
                        ...prev,
                        specialtyId: o?.value ? Number(o.value) : null,
                      }));
                    }}
                  />
                </div>
              </Modal.Body>
              <Modal.Footer>
                <div className="flex gap-2 justify-end w-full">
                  <Button variant="secondary" onPress={closeModal}>
                    Cancelar
                  </Button>
                  <AsyncButton
                    isLoading={updateMutation.isPending}
                    loadingText="Guardando..."
                    variant="primary"
                    onPress={handleSave}
                  >
                    Guardar cambios
                  </AsyncButton>
                </div>
              </Modal.Footer>
            </Modal.Dialog>
          </Modal.Container>
        </Modal.Backdrop>
      </Modal>
    </div>
  );
}

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useNavigate } from "react-router";
import type { SingleValue } from "react-select";
import { AsyncButton } from "../../components/button/AsyncButton";
import { CatalogueSelect } from "../../components/select/CatalogueSelect";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { api } from "../../configs/axios/interceptors";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import { getBranches } from "../../services/branchService";
import { getBranchSpecialties } from "../../services/branchSpecialtyService";
import { getUsers } from "../../services/userService";
import type { ApiResponse } from "../../types/ApiResponse";
import type { BranchResponse } from "../../types/BranchResponse";
import type { UserRequest } from "../../types/UserRequest";
import type { UserResponse } from "../../types/UserResponse";

type Step = "select-doctor" | "select-branch" | "confirm";

export function DoctorTransferPage() {
  const { userId } = useAuth();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const [step, setStep] = useState<Step>("select-doctor");
  const [selectedDoctor, setSelectedDoctor] = useState<UserResponse | null>(
    null,
  );
  const [selectedDoctorOption, setSelectedDoctorOption] = useState<{
    label: string;
    value: string;
  } | null>(null);
  const [newBranchId, setNewBranchId] = useState<number | null>(null);
  const [newBranchName, setNewBranchName] = useState<string>("");

  // Fetch full doctor details when one is selected
  const { data: doctorData, isLoading: doctorLoading } = useQuery({
    queryKey: ["doctor-detail", selectedDoctorOption?.value],
    queryFn: () =>
      getUsers({
        pageNumber: 1,
        pageSize: 1,
        filters: `Id:eq:${selectedDoctorOption!.value} AND State:eq:1`,
        include: "Rol,Branch,Specialty",
        includeTotal: false,
      }),
    enabled: !!selectedDoctorOption?.value,
  });

  // Fetch specialties available at the new branch
  const { data: branchSpecialtiesData } = useQuery({
    queryKey: ["branch-specialties-transfer", newBranchId],
    queryFn: () =>
      getBranchSpecialties({
        pageNumber: 1,
        pageSize: 50,
        filters: `BranchId:eq:${newBranchId} AND State:eq:1`,
        include: "Specialty",
        includeTotal: false,
      }),
    enabled: !!newBranchId,
  });

  const transferMutation = useMutation({
    mutationFn: (payload: UserRequest) =>
      api.patch<unknown, ApiResponse<UserResponse>, UserRequest>(
        "User",
        payload,
      ),
    onSuccess: (res) => {
      if (res.success) {
        toast.success("M├®dico trasladado correctamente");
        queryClient.invalidateQueries({ queryKey: ["doctors"] });
        navigate(nameRoutes.doctorManagement);
      } else {
        toast.danger(res.message ?? "Error al trasladar");
      }
    },
    onError: () => toast.danger("Error inesperado al trasladar"),
  });

  const selectorDoctor = useCallback(
    (item: UserResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const selectorBranch = useCallback(
    (item: BranchResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  // Resolve doctor once loaded
  const doctor =
    doctorData?.success && doctorData.data.length > 0
      ? doctorData.data[0]
      : selectedDoctor;

  const newBranchSpecialtyNames = branchSpecialtiesData?.success
    ? branchSpecialtiesData.data.map((bs) => bs.specialty?.name).filter(Boolean)
    : [];

  const doctorSpecialtyName = doctor?.specialty?.name;
  const specialtyWarning =
    newBranchId &&
    doctorSpecialtyName &&
    newBranchSpecialtyNames.length > 0 &&
    !newBranchSpecialtyNames.includes(doctorSpecialtyName);

  const handleConfirm = () => {
    if (!doctor || !newBranchId) return;
    transferMutation.mutate({
      id: doctor.id,
      state: 1,
      branchId: newBranchId,
      updatedBy: userId,
    });
  };

  const handleDoctorSelect = (
    opt: SingleValue<{ label: string; value: string }> | null,
  ) => {
    setSelectedDoctorOption(opt);
    setSelectedDoctor(null);
    setStep("select-doctor");
    setNewBranchId(null);
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-1">Traslado de M├®dico</h1>
      <p className="text-gray-500 text-sm mb-6">
        Reasigne a un m├®dico de una sede a otra siguiendo los pasos a
        continuaci├│n.
      </p>

      {/* Step indicators */}
      <div className="flex items-center gap-2 mb-8">
        {(["select-doctor", "select-branch", "confirm"] as Step[]).map(
          (s, idx) => {
            const labels = ["Seleccionar m├®dico", "Nueva sede", "Confirmar"];
            const active = step === s;
            const done =
              (s === "select-doctor" &&
                (step === "select-branch" || step === "confirm")) ||
              (s === "select-branch" && step === "confirm");
            return (
              <div key={s} className="flex items-center gap-2">
                <div
                  className={`w-7 h-7 rounded-full flex items-center justify-center text-sm font-bold border-2
                  ${active ? "bg-primary text-white border-primary" : done ? "bg-green-500 text-white border-green-500" : "bg-gray-100 text-gray-400 border-gray-300"}`}
                >
                  {done ? "Ô£ô" : idx + 1}
                </div>
                <span
                  className={`text-sm ${active ? "font-semibold" : "text-gray-400"}`}
                >
                  {labels[idx]}
                </span>
                {idx < 2 && <span className="text-gray-300 mx-1">ÔÇ║</span>}
              </div>
            );
          },
        )}
      </div>

      {/* STEP 1: Select doctor */}
      {(step === "select-doctor" ||
        step === "select-branch" ||
        step === "confirm") && (
        <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-5 mb-4">
          <h2 className="font-semibold mb-3 text-sm text-gray-500 uppercase tracking-wide">
            Paso 1 ÔÇö M├®dico seleccionado
          </h2>
          <CatalogueSelect<UserResponse>
            defaultValue={selectedDoctorOption}
            deps="Rol.Name:eq:Medico AND State:eq:1"
            fieldSearch="Name"
            label="Buscar m├®dico"
            name="doctorId"
            placeholder="Escriba el nombre del m├®dico..."
            queryFn={getUsers}
            selectorFn={selectorDoctor}
            onChange={(opt) => {
              handleDoctorSelect(
                opt as SingleValue<{ label: string; value: string }>,
              );
            }}
          />

          {doctorLoading ? <LoadingComponent /> : null}

          {doctor ? (
            <div className="mt-4 p-3 bg-gray-50 dark:bg-gray-700 rounded-lg text-sm grid grid-cols-2 gap-2">
              <div>
                <span className="font-semibold">Nombre:</span> {doctor.name}
              </div>
              <div>
                <span className="font-semibold">Sede actual:</span>{" "}
                {doctor.branch?.name ?? (
                  <em className="text-orange-500">Sin asignar</em>
                )}
              </div>
              <div>
                <span className="font-semibold">Especialidad:</span>{" "}
                {doctor.specialty?.name ?? (
                  <em className="text-orange-500">Sin asignar</em>
                )}
              </div>
            </div>
          ) : null}

          {doctor && step === "select-doctor" ? (
            <div className="flex justify-end mt-4">
              <Button
                variant="primary"
                onPress={() => setStep("select-branch")}
              >
                Continuar <i className="bi bi-arrow-right ml-1" />
              </Button>
            </div>
          ) : null}
        </div>
      )}

      {/* STEP 2: Select new branch */}
      {(step === "select-branch" || step === "confirm") && (
        <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-5 mb-4">
          <h2 className="font-semibold mb-3 text-sm text-gray-500 uppercase tracking-wide">
            Paso 2 ÔÇö Nueva sede
          </h2>
          <CatalogueSelect<BranchResponse>
            defaultValue={
              newBranchId
                ? { label: newBranchName, value: String(newBranchId) }
                : null
            }
            deps="State:eq:1"
            fieldSearch="Name"
            label="Seleccionar sede de destino"
            name="newBranchId"
            placeholder="Seleccione la nueva sede"
            queryFn={getBranches}
            selectorFn={selectorBranch}
            onChange={(opt) => {
              const o = opt as SingleValue<{ label: string; value: string }>;
              setNewBranchId(o?.value ? Number(o.value) : null);
              setNewBranchName(o?.label ?? "");
              if (step === "confirm") setStep("select-branch");
            }}
          />

          {specialtyWarning ? (
            <div className="mt-3 p-3 bg-yellow-50 border border-yellow-300 rounded-lg text-yellow-800 text-sm flex gap-2">
              <i className="bi bi-exclamation-triangle-fill mt-0.5 shrink-0" />
              <span>
                La sede seleccionada no ofrece la especialidad{" "}
                <strong>{doctorSpecialtyName}</strong>. Considere tambi├®n
                actualizar la especialidad del m├®dico despu├®s del traslado.
              </span>
            </div>
          ) : null}

          {newBranchSpecialtyNames.length > 0 && (
            <p className="text-xs text-gray-400 mt-2">
              Especialidades disponibles en esta sede:{" "}
              {newBranchSpecialtyNames.join(", ")}
            </p>
          )}

          {newBranchId && step === "select-branch" ? (
            <div className="flex justify-between mt-4">
              <Button
                variant="secondary"
                onPress={() => setStep("select-doctor")}
              >
                <i className="bi bi-arrow-left mr-1" /> Atr├ís
              </Button>
              <Button variant="primary" onPress={() => setStep("confirm")}>
                Continuar <i className="bi bi-arrow-right ml-1" />
              </Button>
            </div>
          ) : null}
        </div>
      )}

      {/* STEP 3: Confirm */}
      {step === "confirm" && doctor && newBranchId ? (
        <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-5">
          <h2 className="font-semibold mb-3 text-sm text-gray-500 uppercase tracking-wide">
            Paso 3 ÔÇö Confirmar traslado
          </h2>
          <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 rounded-lg text-sm space-y-2">
            <p>
              <span className="font-semibold">M├®dico:</span> {doctor.name}
            </p>
            <p>
              <span className="font-semibold">Sede actual:</span>{" "}
              {doctor.branch?.name ?? "Sin asignar"}{" "}
              <i className="bi bi-arrow-right" />{" "}
              <span className="font-semibold text-blue-700">
                {newBranchName}
              </span>
            </p>
            <p>
              <span className="font-semibold">Especialidad:</span>{" "}
              {doctor.specialty?.name ?? "Sin asignar"}
            </p>
          </div>

          {specialtyWarning ? (
            <div className="mt-3 p-3 bg-yellow-50 border border-yellow-300 rounded-lg text-yellow-800 text-sm flex gap-2">
              <i className="bi bi-exclamation-triangle-fill mt-0.5 shrink-0" />
              <span>
                La nueva sede no ofrece <strong>{doctorSpecialtyName}</strong>.
                Recuerde actualizar la especialidad.
              </span>
            </div>
          ) : null}

          <div className="flex justify-between mt-5">
            <Button
              variant="secondary"
              onPress={() => setStep("select-branch")}
            >
              <i className="bi bi-arrow-left mr-1" /> Atr├ís
            </Button>
            <AsyncButton
              isLoading={transferMutation.isPending}
              loadingText="Trasladando..."
              variant="primary"
              onPress={handleConfirm}
            >
              <i className="bi bi-check-circle mr-1" />
              Confirmar Traslado
            </AsyncButton>
          </div>
        </div>
      ) : null}
    </div>
  );
}

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useNavigate, useSearchParams } from "react-router";
import type { SingleValue } from "react-select";
import { AsyncButton } from "../../components/button/AsyncButton";
import { CatalogueSelect } from "../../components/select/CatalogueSelect";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import {
  getAppointments,
  partialUpdateAppointment,
} from "../../services/appointmentService";
import { getUsers } from "../../services/userService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import type { UserResponse } from "../../types/UserResponse";

export function AppointmentReassignPage() {
  const { userId } = useAuth();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [searchParams] = useSearchParams();

  const preloadedId = searchParams.get("appointmentId");

  const [searchQuery, setSearchQuery] = useState(preloadedId ?? "");
  const [searchInput, setSearchInput] = useState(preloadedId ?? "");
  const [searchType, setSearchType] = useState<"dpi" | "id">(
    preloadedId ? "id" : "dpi",
  );
  const [selectedAppointment, setSelectedAppointment] =
    useState<AppointmentResponse | null>(null);
  const [newDoctorId, setNewDoctorId] = useState<number | null>(null);
  const [notes, setNotes] = useState("");

  // Search appointments (only Pagada status)
  const { data: searchData, isLoading: searchLoading } = useQuery({
    queryKey: ["reassign-search", searchQuery, searchType],
    queryFn: () => {
      const filter =
        searchType === "dpi"
          ? `Patient.IdentificationDocument:eq:${searchQuery}`
          : `Id:eq:${searchQuery}`;
      return getAppointments({
        pageNumber: 1,
        pageSize: 20,
        filters: `${filter} AND State:eq:1 AND AppointmentStatus.Name:eq:Pagada`,
        include: "Specialty,Branch,AppointmentStatus,Patient,Doctor",
        includeTotal: false,
      });
    },
    enabled: !!searchQuery,
  });

  // Fetch available doctors for selected appointment
  const doctorFilters = selectedAppointment
    ? `Rol.Name:eq:Medico AND State:eq:1 AND BranchId:eq:${selectedAppointment.branchId} AND SpecialtyId:eq:${selectedAppointment.specialtyId}`
    : "";

  const { data: doctorsData, isLoading: doctorsLoading } = useQuery({
    queryKey: [
      "reassign-doctors",
      selectedAppointment?.branchId,
      selectedAppointment?.specialtyId,
    ],
    queryFn: () =>
      getUsers({
        pageNumber: 1,
        pageSize: 50,
        filters: doctorFilters,
        include: "Rol,Branch,Specialty",
        includeTotal: false,
      }),
    enabled: !!selectedAppointment,
  });

  const reassignMutation = useMutation({
    mutationFn: () =>
      partialUpdateAppointment({
        id: selectedAppointment!.id,
        doctorId: newDoctorId,
        notes: notes || undefined,
        updatedBy: userId,
      }),
    onSuccess: (res) => {
      if (res.success) {
        toast.success("M├®dico reasignado correctamente");
        queryClient.invalidateQueries({ queryKey: ["appointments"] });
        queryClient.invalidateQueries({ queryKey: ["reassign-search"] });
        navigate(nameRoutes.appointment);
      } else {
        toast.danger(res.message ?? "Error al reasignar");
      }
    },
    onError: () => toast.danger("Error inesperado al reasignar"),
  });

  const selectorDoctor = useCallback(
    (item: UserResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const handleSearch = () => {
    if (!searchInput.trim()) return;
    setSearchQuery(searchInput.trim());
    setSelectedAppointment(null);
    setNewDoctorId(null);
  };

  const appointments = searchData?.success ? searchData.data : [];
  const availableDoctors = doctorsData?.success ? doctorsData.data : [];

  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="flex items-center gap-3 mb-1">
        <Button
          size="sm"
          variant="secondary"
          onPress={() => navigate(nameRoutes.appointment)}
        >
          <i className="bi bi-arrow-left mr-1" /> Volver
        </Button>
        <h1 className="text-2xl font-bold">Reasignar M├®dico</h1>
      </div>
      <p className="text-gray-500 text-sm mb-6">
        Busque una cita pagada y asigne un nuevo m├®dico de la misma sede y
        especialidad.
      </p>

      {/* Search bar */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-4 mb-5">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="flex gap-2">
            <button
              className={`px-3 py-2 rounded-lg text-sm font-medium border transition-colors
                ${searchType === "dpi" ? "bg-primary text-white border-primary" : "bg-gray-100 border-gray-200 text-gray-600"}`}
              onClick={() => setSearchType("dpi")}
            >
              DPI
            </button>
            <button
              className={`px-3 py-2 rounded-lg text-sm font-medium border transition-colors
                ${searchType === "id" ? "bg-primary text-white border-primary" : "bg-gray-100 border-gray-200 text-gray-600"}`}
              onClick={() => setSearchType("id")}
            >
              # Cita
            </button>
          </div>
          <input
            className="flex-1 border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
            placeholder={
              searchType === "dpi"
                ? "Ingrese DPI del paciente..."
                : "Ingrese n├║mero de cita..."
            }
            type="text"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSearch()}
          />
          <Button variant="primary" onPress={handleSearch}>
            <i className="bi bi-search mr-1" /> Buscar
          </Button>
        </div>
      </div>

      {/* Search results */}
      {searchLoading ? <LoadingComponent /> : null}

      {!searchLoading && searchQuery && appointments.length === 0 ? (
        <div className="text-center py-10 text-gray-400">
          <i className="bi bi-calendar-x text-4xl block mb-3" />
          <p>No se encontraron citas pagadas con los par├ímetros ingresados.</p>
        </div>
      ) : null}

      {appointments.length > 0 && !selectedAppointment && (
        <div className="mb-5">
          <h2 className="font-semibold text-sm text-gray-500 uppercase tracking-wide mb-3">
            Seleccione la cita a reasignar
          </h2>
          <div className="space-y-3">
            {appointments.map((appt) => (
              <div
                key={appt.id}
                className="bg-white dark:bg-gray-800 border rounded-xl p-4 flex justify-between items-start gap-4 hover:border-primary/60 transition-colors cursor-pointer"
                onClick={() => {
                  setSelectedAppointment(appt);
                  setNewDoctorId(null);
                }}
              >
                <div className="text-sm space-y-1">
                  <p className="font-bold">
                    {appt.patient?.name ?? `Paciente #${appt.patientId}`}
                  </p>
                  <p>
                    <span className="font-semibold">Cita #:</span> {appt.id}
                  </p>
                  <p>
                    <span className="font-semibold">Fecha:</span>{" "}
                    {appt.appointmentDate}
                  </p>
                  <p>
                    <span className="font-semibold">Especialidad:</span>{" "}
                    {appt.specialty?.name ?? "ÔÇö"}
                  </p>
                  <p>
                    <span className="font-semibold">Sede:</span>{" "}
                    {appt.branch?.name ?? "ÔÇö"}
                  </p>
                  <p>
                    <span className="font-semibold">M├®dico actual:</span>{" "}
                    {appt.doctor?.name ?? (
                      <em className="text-orange-500">Sin asignar</em>
                    )}
                  </p>
                </div>
                <Button size="sm" variant="primary">
                  Seleccionar
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Reassign form */}
      {selectedAppointment ? (
        <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-5">
          <div className="flex justify-between items-start mb-4">
            <h2 className="font-semibold text-sm text-gray-500 uppercase tracking-wide">
              Reasignar cita #{selectedAppointment.id}
            </h2>
            <Button
              size="sm"
              variant="secondary"
              onPress={() => {
                setSelectedAppointment(null);
                setNewDoctorId(null);
              }}
            >
              Cambiar cita
            </Button>
          </div>

          {/* Appointment summary */}
          <div className="p-3 bg-gray-50 dark:bg-gray-700 rounded-lg text-sm grid grid-cols-2 md:grid-cols-4 gap-2 mb-5">
            <div>
              <span className="font-semibold">Paciente:</span>{" "}
              {selectedAppointment.patient?.name}
            </div>
            <div>
              <span className="font-semibold">Fecha:</span>{" "}
              {selectedAppointment.appointmentDate}
            </div>
            <div>
              <span className="font-semibold">Especialidad:</span>{" "}
              {selectedAppointment.specialty?.name ?? "ÔÇö"}
            </div>
            <div>
              <span className="font-semibold">Sede:</span>{" "}
              {selectedAppointment.branch?.name ?? "ÔÇö"}
            </div>
            <div className="col-span-2 md:col-span-4">
              <span className="font-semibold">M├®dico actual:</span>{" "}
              {selectedAppointment.doctor?.name ?? (
                <em className="text-orange-500">Sin m├®dico asignado</em>
              )}
            </div>
          </div>

          {/* Doctor picker */}
          {doctorsLoading ? <LoadingComponent /> : null}
          {!doctorsLoading && availableDoctors.length === 0 && (
            <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-lg text-yellow-800 text-sm mb-4">
              <i className="bi bi-exclamation-triangle mr-2" />
              No hay m├®dicos disponibles en esta sede con esta especialidad.
            </div>
          )}
          {!doctorsLoading && availableDoctors.length > 0 && (
            <div className="mb-4">
              <CatalogueSelect<UserResponse>
                isRequired
                defaultValue={null}
                deps={doctorFilters}
                fieldSearch="Name"
                label="Nuevo m├®dico"
                name="newDoctorId"
                placeholder="Seleccione el nuevo m├®dico..."
                queryFn={getUsers}
                selectorFn={selectorDoctor}
                onChange={(opt) => {
                  const o = opt as SingleValue<{
                    label: string;
                    value: string;
                  }>;
                  setNewDoctorId(o?.value ? Number(o.value) : null);
                }}
              />
            </div>
          )}

          {/* Notes */}
          <div className="mb-5">
            <label className="text-xs text-gray-500 block mb-1">
              Notas (opcional)
            </label>
            <textarea
              className="w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 resize-none"
              placeholder="Motivo de la reasignaci├│n..."
              rows={3}
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>

          <div className="flex justify-end gap-3">
            <Button
              variant="secondary"
              onPress={() => navigate(nameRoutes.appointment)}
            >
              Cancelar
            </Button>
            <AsyncButton
              isDisabled={!newDoctorId}
              isLoading={reassignMutation.isPending}
              loadingText="Reasignando..."
              variant="primary"
              onPress={() => reassignMutation.mutate()}
            >
              <i className="bi bi-person-check mr-1" />
              Confirmar Reasignaci├│n
            </AsyncButton>
          </div>
        </div>
      ) : null}
    </div>
  );
}

import { Button } from "@heroui/react";
import { useQuery } from "@tanstack/react-query";
import { useNavigate, useParams } from "react-router";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { nameRoutes } from "../../configs/constants";
import { getAppointmentById } from "../../services/appointmentService";

const statusColors: Record<string, string> = {
  "Pendiente de Pago": "bg-yellow-100 text-yellow-800 border-yellow-200",
  Confirmada: "bg-green-100 text-green-800 border-green-200",
  "Signos Vitales": "bg-purple-100 text-purple-800 border-purple-200",
  "En Espera": "bg-orange-100 text-orange-800 border-orange-200",
  "Consulta M├®dica": "bg-blue-100 text-blue-800 border-blue-200",
  Evaluado: "bg-teal-100 text-teal-800 border-teal-200",
  Laboratorio: "bg-indigo-100 text-indigo-800 border-indigo-200",
  Farmacia: "bg-cyan-100 text-cyan-800 border-cyan-200",
  "Atenci├│n Finalizada": "bg-gray-100 text-gray-700 border-gray-200",
  "No Asisti├│": "bg-red-100 text-red-800 border-red-200",
  Cancelada: "bg-red-100 text-red-800 border-red-200",
};

function DetailRow({
  label,
  value,
  icon,
}: {
  readonly label: string;
  readonly value: string;
  readonly icon?: string;
}) {
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
        {icon ? <i className={`bi ${icon} mr-1`} /> : null}
        {label}
      </span>
      <span className="text-sm font-medium text-gray-800 dark:text-gray-100">
        {value || "ÔÇö"}
      </span>
    </div>
  );
}

export function AppointmentViewPage() {
  const { id } = useParams();
  const navigate = useNavigate();

  const { data, isLoading, error } = useQuery({
    queryKey: ["appointment-view", id],
    queryFn: () => getAppointmentById(Number(id)),
  });

  if (isLoading) return <LoadingComponent />;

  if (!data?.success || !data.data) {
    return (
      <div className="p-8 text-center text-gray-400">
        <i className="bi bi-exclamation-triangle text-4xl block mb-3" />
        <p>Cita no encontrada. {error instanceof Error ? error.message : ""}</p>
        <Button
          className="mt-4"
          variant="secondary"
          onPress={() => navigate(nameRoutes.appointment)}
        >
          Volver a Citas
        </Button>
      </div>
    );
  }

  const appt = data.data;
  const statusName = appt.appointmentStatus?.name ?? "";
  const statusClass =
    statusColors[statusName] ?? "bg-gray-100 text-gray-700 border-gray-200";

  return (
    <div className="max-w-3xl mx-auto p-6">
      <div className="flex items-center gap-3 mb-6">
        <Button
          size="sm"
          variant="secondary"
          onPress={() => navigate(nameRoutes.appointment)}
        >
          <i className="bi bi-arrow-left mr-1" /> Volver
        </Button>
        <h1 className="text-2xl font-bold">Detalle de Cita #{appt.id}</h1>
      </div>

      {/* Status banner */}
      <div
        className={`mb-6 rounded-xl border p-4 flex items-center justify-between ${statusClass}`}
      >
        <div>
          <p className="text-sm font-semibold">Estado actual</p>
          <p className="text-lg font-bold">{statusName || "Desconocido"}</p>
        </div>
        <span
          className={`px-3 py-1 rounded-full text-sm font-bold border ${statusClass}`}
        >
          {statusName}
        </span>
      </div>

      {/* Details grid */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-6 mb-6">
        <h2 className="font-bold text-base mb-4">Informaci├│n de la Cita</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-5">
          <DetailRow icon="bi-hash" label="No. Cita" value={String(appt.id)} />
          <DetailRow
            icon="bi-person"
            label="Paciente"
            value={appt.patient?.name ?? `#${appt.patientId}`}
          />
          <DetailRow
            icon="bi-person-badge"
            label="M├®dico"
            value={
              appt.doctor?.name ??
              (appt.doctorId ? `#${appt.doctorId}` : "Sin asignar")
            }
          />
          <DetailRow
            icon="bi-hospital"
            label="Especialidad"
            value={appt.specialty?.name ?? ""}
          />
          <DetailRow
            icon="bi-building"
            label="Sede"
            value={appt.branch?.name ?? ""}
          />
          <DetailRow
            icon="bi-calendar3"
            label="Fecha y Hora"
            value={appt.appointmentDate}
          />
          <DetailRow
            icon="bi-cash-coin"
            label="Monto"
            value={`Q${appt.amount?.toFixed(2) ?? "0.00"}`}
          />
          <DetailRow
            icon="bi-flag"
            label="Prioridad"
            value={appt.priority > 0 ? "­ƒÜ¿ Emergencia" : "Normal"}
          />
          {appt.arrivalTime ? (
            <DetailRow
              icon="bi-clock-history"
              label="Hora de Llegada"
              value={appt.arrivalTime}
            />
          ) : null}
        </div>
      </div>

      {/* Reason */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-6 mb-6">
        <h2 className="font-bold text-base mb-2">Motivo de Consulta</h2>
        <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
          {appt.reason || "Sin motivo registrado."}
        </p>
      </div>

      {/* Notes */}
      {appt.notes ? (
        <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-6 mb-6">
          <h2 className="font-bold text-base mb-2">Notas</h2>
          <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
            {appt.notes}
          </p>
        </div>
      ) : null}

      {/* Metadata */}
      <div className="bg-gray-50 dark:bg-gray-800/50 rounded-xl border p-4 text-xs text-gray-500 grid grid-cols-2 md:grid-cols-4 gap-3">
        <div>
          <span className="font-semibold">Creado:</span> {appt.createdAt}
        </div>
        <div>
          <span className="font-semibold">Creado por:</span> #{appt.createdBy}
        </div>
        {appt.updatedAt ? (
          <div>
            <span className="font-semibold">Actualizado:</span> {appt.updatedAt}
          </div>
        ) : null}
        {appt.updatedBy ? (
          <div>
            <span className="font-semibold">Actualizado por:</span> #
            {appt.updatedBy}
          </div>
        ) : null}
      </div>
    </div>
  );
}

import { toast } from "@heroui/react";
import { useQuery } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useNavigate } from "react-router";

import { DynamicCalendar } from "../../components/portal/DynamicCalendar";
import { CatalogueSelect } from "../../components/select/CatalogueSelect";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import { createAppointment } from "../../services/appointmentService";
import { getBranches } from "../../services/branchService";
import {
  getDoctorsByBranchAndSpecialty,
  getSpecialtiesByBranch,
} from "../../services/patientPortalService";
import { getUsers } from "../../services/userService";
import type { BranchResponse } from "../../types/BranchResponse";
import type { DoctorResponse } from "../../types/PatientPortalTypes";
import type { SpecialtyResponse } from "../../types/SpecialtyResponse";
import type { UserResponse } from "../../types/UserResponse";
import { formatDateLong, formatTime } from "../../utils/dateFormatter";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------
const CONSULTATION_FEE = 150.0;
const TOTAL_STEPS = 6;

const SPECIALTY_ICONS: Record<string, string> = {
  Cardiologia: "bi-heart-pulse",
  Pediatria: "bi-person-hearts",
  Neurologia: "bi-brain",
  Ortopedia: "bi-bandaid",
  Ginecologia: "bi-gender-female",
  Dermatologia: "bi-droplet",
  Oftalmologia: "bi-eye",
  "Medicina General": "bi-clipboard2-pulse",
};

// ---------------------------------------------------------------------------
// Wizard state
// ---------------------------------------------------------------------------
interface WizardState {
  step: 1 | 2 | 3 | 4 | 5 | 6;
  patient: { id: number; name: string } | null;
  branch: BranchResponse | null;
  specialty: SpecialtyResponse | null;
  doctor: DoctorResponse | null;
  appointmentDate: Date | null;
}

// ---------------------------------------------------------------------------
// StepIndicator
// ---------------------------------------------------------------------------
function StepIndicator({
  current,
  total,
}: {
  readonly current: number;
  readonly total: number;
}) {
  return (
    <div className="mb-8 flex items-center justify-center gap-2">
      {Array.from({ length: total }, (_, i) => {
        const step = i + 1;
        const isActive = step === current;
        const isDone = step < current;
        return (
          <div key={step} className="flex items-center gap-2">
            <div
              className={`flex h-8 w-8 items-center justify-center rounded-full text-sm font-bold transition-colors ${
                isActive
                  ? "bg-blue-600 text-white"
                  : isDone
                    ? "bg-green-500 text-white"
                    : "bg-gray-200 text-gray-500 dark:bg-gray-700 dark:text-gray-400"
              }`}
            >
              {isDone ? <i className="bi bi-check-lg" /> : step}
            </div>
            {step < total && (
              <div
                className={`h-0.5 w-8 ${isDone ? "bg-green-400" : "bg-gray-200 dark:bg-gray-700"}`}
              />
            )}
          </div>
        );
      })}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 1 ÔÇô Select Patient
// ---------------------------------------------------------------------------
function Step1Patient({
  onSelect,
}: {
  readonly onSelect: (patient: { id: number; name: string }) => void;
}) {
  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Seleccione un Paciente
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        Busque y seleccione el paciente para la cita.
      </p>
      <CatalogueSelect<UserResponse>
        isRequired
        deps="Rol.Name:eq:Paciente AND State:eq:1"
        fieldSearch="Name"
        label="Paciente"
        placeholder="Buscar paciente por nombre..."
        queryFn={getUsers}
        selectorFn={(user) => ({
          label: `${user.name} ÔÇö ${user.identificationDocument}`,
          value: String(user.id),
        })}
        onChange={(option) => {
          if (option && "value" in option) {
            onSelect({ id: Number(option.value), name: option.label });
          }
        }}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 2 ÔÇô Select Branch
// ---------------------------------------------------------------------------
function Step2Branch({
  onSelect,
  onBack,
}: {
  readonly onSelect: (branch: BranchResponse) => void;
  readonly onBack: () => void;
}) {
  const { data, isLoading, isError } = useQuery({
    queryKey: ["admin-book-branches"],
    queryFn: () =>
      getBranches({
        pageNumber: 1,
        pageSize: 50,
        filters: "State:eq:1",
        include: null,
        includeTotal: false,
      }),
    staleTime: 1000 * 60 * 10,
  });

  const branches = data?.success ? data.data : [];

  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Seleccione una Sede
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        Elija la sede donde se atender├í el paciente.
      </p>

      {isLoading ? (
        <div className="flex justify-center py-10">
          <i className="bi bi-hourglass-split animate-spin text-3xl text-blue-500" />
        </div>
      ) : null}
      {isError ? (
        <div className="rounded-xl bg-red-50 p-4 text-red-700 dark:bg-red-900/20 dark:text-red-400">
          <i className="bi bi-exclamation-triangle mr-2" />
          Error al cargar sedes. Intente de nuevo.
        </div>
      ) : null}
      {!isLoading && !isError && branches.length === 0 && (
        <p className="text-center text-gray-400">No hay sedes disponibles.</p>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        {branches.map((b) => (
          <button
            key={b.id}
            className="flex items-start gap-4 rounded-xl border border-gray-200 bg-white p-5 text-left shadow-sm transition-all hover:border-blue-400 hover:shadow-md dark:border-gray-700 dark:bg-gray-900/50 dark:hover:border-blue-500"
            type="button"
            onClick={() => onSelect(b)}
          >
            <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-blue-100 dark:bg-blue-900">
              <i className="bi bi-building text-2xl text-blue-600 dark:text-blue-300" />
            </div>
            <div>
              <p className="font-semibold text-gray-800 dark:text-gray-100">
                {b.name}
              </p>
              {b.address ? (
                <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                  <i className="bi bi-geo-alt mr-1" />
                  {b.address}
                </p>
              ) : null}
              {b.phone ? (
                <p className="mt-0.5 text-xs text-gray-500 dark:text-gray-400">
                  <i className="bi bi-telephone mr-1" />
                  {b.phone}
                </p>
              ) : null}
            </div>
            <i className="bi bi-chevron-right ml-auto self-center text-gray-400" />
          </button>
        ))}
      </div>

      <button
        className="mt-6 flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
        type="button"
        onClick={onBack}
      >
        <i className="bi bi-arrow-left" />
        Volver a paciente
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
