});

interface ForgotPasswordPageProps {
  /** Where to link "back to login" ÔÇö defaults to admin login */
  readonly loginRoute?: string;
}

export function ForgotPasswordPage({
  loginRoute = nameRoutes.login,
}: ForgotPasswordPageProps) {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSubmit = useCallback(
    async (e: FormEvent) => {
      e.preventDefault();
      setError("");

      const result = emailSchema.safeParse({ email });
      if (!result.success) {
        setError(result.error.issues[0].message);
        return;
      }

      setIsLoading(true);
      try {
        const response = await recoveryPassword(email.trim());
        if (response.success) {
          setSent(true);
        } else {
          // Always show generic message to prevent email enumeration
          setSent(true);
        }
      } catch {
        setError(
          "No se pudo conectar con el servidor. Intente de nuevo m├ís tarde.",
        );
      } finally {
        setIsLoading(false);
      }
    },
    [email],
  );

  return (
    <section className="flex items-center justify-center min-h-[calc(100vh-140px)] px-4 py-12">
      <div className="w-full max-w-md">
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 p-8">
