import { getRoleFromToken } from "../../utils/jwt";

export function Component() {
  const { signIn } = useAuth();

  const [form, setForm] = useState({ userName: "", password: "" });
  const [apiError, setApiError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleSubmit = useCallback(
    async (e: FormEvent) => {
      e.preventDefault();
      if (!form.userName || !form.password) {
        setApiError("Ingrese usuario y contrase├▒a.");
        return;
      }

      setIsLoading(true);
      setApiError("");

      try {
        const response = await authenticateUser(form);

        if (!response.success) {
          setApiError("Usuario o contrase├▒a incorrectos.");
          return;
        }

        const auth = response.data;

        // Block patients from admin panel
        const roleName = getRoleFromToken(auth.token);
        if (roleName === "Paciente") {
          setApiError(
            "Este acceso es exclusivo para personal del hospital. Si es paciente, use el portal de pacientes.",
          );
          return;
        }

        signIn({
          email: auth.email,
          token: auth.token,
          userName: auth.userName,
          name: auth.name,
          operations: auth.operations,
          redirect: false,
          isLoggedIn: true,
          userId: auth.userId,
          timezoneIanaId: auth.timezoneIanaId || "America/Guatemala",
        });
      } catch {
        setApiError(
          "No se pudo conectar con el servidor. Intente de nuevo m├ís tarde.",
