import { useCallback } from "react";
import { useNavigate } from "react-router";
import { BranchSpecialtyResponseColumns } from "../../components/column/BranchSpecialtyResponseColumns";
import { TableServer } from "../../components/table/TableServer";
import { nameRoutes } from "../../configs/constants";
import { getBranchSpecialties } from "../../services/branchSpecialtyService";
import { useBranchSpecialtyStore } from "../../stores/useBranchSpecialtyStore";
import { customStyles } from "../../theme/tableTheme";

export function BranchSpecialtyPage() {
  const { filters, setFilters } = useBranchSpecialtyStore();
  const navigate = useNavigate();

  const queryFn = useCallback(
    async (filters: string, page: number, pageSize: number) => {
      return getBranchSpecialties({
        pageNumber: page,
        pageSize,
        filters,
        include: "Branch,Specialty",
        includeTotal: false,
      });
    },
    [],
  );

  return (
    <div>
      <div className="mb-4 flex items-center justify-between">
        <h1 className="text-2xl font-bold">Especialidades por Sede</h1>
        <button
          className="flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white hover:bg-blue-700 transition-colors"
          type="button"
          onClick={() => navigate(nameRoutes.branchSpecialtyCreate)}
        >
          <i className="bi bi-plus-circle" />
          Asignar Especialidad
        </button>
      </div>
      <TableServer
        hasFilters
        columns={BranchSpecialtyResponseColumns}
        filters={filters}
        queryFn={queryFn}
        queryKey="branch-specialties"
        setFilters={setFilters}
        styles={customStyles}
        text="asignaciones"
        title="Especialidades por Sede"
      />
    </div>
  );
}

import { toast } from "@heroui/react";
import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useNavigate } from "react-router";
import type { SingleValue } from "react-select";
import { AsyncButton } from "../../components/button/AsyncButton";
import { CatalogueSelect } from "../../components/select/CatalogueSelect";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import { getBranches } from "../../services/branchService";
import { createBranchSpecialty } from "../../services/branchSpecialtyService";
import { getSpecialties } from "../../services/specialtyService";
import type { BranchResponse } from "../../types/BranchResponse";
import type { SpecialtyResponse } from "../../types/SpecialtyResponse";

export function CreateBranchSpecialtyPage() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { userId } = useAuth();

  const [branchId, setBranchId] = useState<number | null>(null);
  const [specialtyId, setSpecialtyId] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const selectorBranch = useCallback(
    (item: BranchResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const selectorSpecialty = useCallback(
    (item: SpecialtyResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const handleSubmit = useCallback(async () => {
    setError(null);
    if (!branchId) {
      setError("Debe seleccionar una sede.");
      return;
    }
    if (!specialtyId) {
      setError("Debe seleccionar una especialidad.");
      return;
    }

    setLoading(true);
    try {
      const response = await createBranchSpecialty({
        branchId,
        specialtyId,
        state: 1,
        createdBy: userId,
      });

      if (response.success) {
        toast.success("Especialidad asignada a la sede correctamente");
        await queryClient.invalidateQueries({
          queryKey: ["branch-specialties"],
        });
        navigate(nameRoutes.branchSpecialty);
      } else {
        setError(response.message ?? "Error al crear la asignaci├│n");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error inesperado");
    } finally {
      setLoading(false);
    }
  }, [branchId, specialtyId, userId, navigate, queryClient]);

  return (
    <div className="max-w-lg mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        Asignar Especialidad a Sede
      </h1>

      <div className="flex flex-col gap-5">
        <CatalogueSelect<BranchResponse>
          isRequired
          defaultValue={null}
          deps="State:eq:1"
          fieldSearch="Name"
          label="Sede"
          name="branchId"
          placeholder="Seleccione una sede"
          queryFn={getBranches}
          selectorFn={selectorBranch}
          onChange={(opt) => {
            const o = opt as SingleValue<{ label: string; value: string }>;
            setBranchId(o?.value ? Number(o.value) : null);
          }}
        />

        <CatalogueSelect<SpecialtyResponse>
          isRequired
          defaultValue={null}
          deps="State:eq:1"
          fieldSearch="Name"
          label="Especialidad"
          name="specialtyId"
          placeholder="Seleccione una especialidad"
          queryFn={getSpecialties}
          selectorFn={selectorSpecialty}
          onChange={(opt) => {
            const o = opt as SingleValue<{ label: string; value: string }>;
            setSpecialtyId(o?.value ? Number(o.value) : null);
          }}
        />

        {error ? (
          <p className="text-sm text-red-600 flex items-center gap-1">
            <i className="bi bi-exclamation-circle" />
            {error}
          </p>
        ) : null}

        <div className="flex gap-3 justify-end mt-2">
          <AsyncButton
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() => navigate(nameRoutes.branchSpecialty)}
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            isLoading={loading}
            loadingText="Guardando..."
            size="lg"
            type="button"
            variant="primary"
            onClick={handleSubmit}
          >
            Asignar
          </AsyncButton>
        </div>
      </div>
    </div>
  );
}

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { OptionsSelect } from "../../components/select/OptionsSelect";
import { PaymentReceipt } from "../../components/shared/PaymentReceipt";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { getAppointments } from "../../services/appointmentService";
import { createPayment } from "../../services/paymentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import type {
  PaymentRequest,
  PaymentResponse,
} from "../../types/PaymentResponse";
import { calculateChange } from "../../utils/calculateChange";
import { generateIdempotencyKey } from "../../utils/generateIdempotencyKey";

const PAYMENT_METHODS = [
  { label: "Efectivo (Q)", value: "0" },
  { label: "Visa", value: "1" },
  { label: "Mastercard", value: "2" },
  { label: "D├®bito", value: "3" },
];

export function CashierPage() {
  const [searchValue, setSearchValue] = useState("");
  const [searchType, setSearchType] = useState<"dpi" | "id">("dpi");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedAppointment, setSelectedAppointment] =
    useState<AppointmentResponse | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<number>(0);
  const [amountReceived, setAmountReceived] = useState<string>("");
  const [cardLastFour, setCardLastFour] = useState<string>("");
  const [paymentSuccess, setPaymentSuccess] = useState<{
    payment: PaymentResponse;
    change: number;
  } | null>(null);
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ["cashier-search", searchQuery, searchType],
    queryFn: () => {
      if (!searchQuery)
        return Promise.resolve({
          success: true as const,
          data: [],
          message: "",
          totalResults: 0,
        });
      const filter =
        searchType === "dpi"
          ? `Patient.IdentificationDocument:eq:${searchQuery} AND AppointmentStatus.Name:eq:Pendiente`
          : `Id:eq:${searchQuery} AND AppointmentStatus.Name:eq:Pendiente`;
      return getAppointments({
        pageNumber: 1,
        pageSize: 20,
        filters: `${filter} AND State:eq:1`,
        include: "Specialty,Branch,AppointmentStatus,Patient",
        includeTotal: false,
      });
    },
    enabled: !!searchQuery,
  });

  const paymentMutation = useMutation({
    mutationFn: (paymentData: PaymentRequest) => createPayment(paymentData),
    onSuccess: (response) => {
      if (response.success && response.data) {
        const payment = response.data as PaymentResponse;
        const change =
          paymentMethod === 0
            ? Math.max(
                0,
                calculateChange(
                  Number(amountReceived),
                  selectedAppointment?.amount ?? 0,
                ),
              )
            : 0;
        setPaymentSuccess({ payment, change });
        const patientName = selectedAppointment?.patient?.name ?? "Paciente";
        toast.success(
          `┬íPago registrado exitosamente! Paciente: ${patientName}. La cita ha sido actualizada a estado "Pagada".`,
        );
        queryClient.invalidateQueries({ queryKey: ["cashier-search"] });
      } else {
        const msg = response.message ?? "";
        if (
          msg.toLowerCase().includes("rechaz") ||
          msg.toLowerCase().includes("declined")
        ) {
          toast.danger(
            "La transacci├│n con tarjeta fue rechazada por el banco. Solicite al paciente otro m├®todo de pago.",
          );
        } else {
          toast.danger(
            `Error al procesar el pago: ${msg || "Intente nuevamente."}`,
          );
        }
      }
    },
    onError: () =>
      toast.danger(
        "Error de comunicaci├│n con el sistema de pagos. Intente nuevamente.",
      ),
  });

  const handleSearch = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      if (!searchValue.trim()) {
        toast.danger("Ingrese un n├║mero de cita o DPI para buscar");
        return;
      }
      setSearchQuery(searchValue.trim());
      setSelectedAppointment(null);
      setPaymentSuccess(null);
    },
    [searchValue],
  );

  const handleSelectAppointment = useCallback(
    (appointment: AppointmentResponse) => {
      setSelectedAppointment(appointment);
      setPaymentSuccess(null);
      setAmountReceived(String(appointment.amount));
    },
    [],
  );

  const handlePay = useCallback(() => {
    if (!selectedAppointment) return;

    if (paymentMethod === 0) {
      const received = Number(amountReceived);
      if (received < selectedAppointment.amount) {
        toast.danger(
          `El monto recibido (Q${received}) es menor al monto a cobrar (Q${selectedAppointment.amount})`,
        );
        return;
      }
    }

    if (
      (paymentMethod === 1 || paymentMethod === 2 || paymentMethod === 3) &&
      cardLastFour.length !== 4
    ) {
      toast.danger("Ingrese los ├║ltimos 4 d├¡gitos de la tarjeta");
      return;
    }

    const paymentData: PaymentRequest = {
      appointmentId: selectedAppointment.id,
      amount: selectedAppointment.amount,
      paymentMethod,
      paymentType: 0, // Consulta
      paymentStatus: 1, // Completado
      paymentDate: new Date().toISOString(),
      idempotencyKey: generateIdempotencyKey(),
      amountReceived: paymentMethod === 0 ? Number(amountReceived) : null,
      changeAmount:
        paymentMethod === 0
          ? Math.max(
              0,
              calculateChange(
                Number(amountReceived),
                selectedAppointment.amount,
              ),
            )
          : null,
      cardLastFourDigits: paymentMethod !== 0 ? cardLastFour : null,
      state: 1,
    };

    paymentMutation.mutate(paymentData);
  }, [
    selectedAppointment,
    paymentMethod,
    amountReceived,
    cardLastFour,
    paymentMutation,
  ]);

  const appointments = data?.success ? data.data : [];
  const change =
    paymentMethod === 0 && selectedAppointment
      ? Math.max(
          0,
          calculateChange(Number(amountReceived), selectedAppointment.amount),
        )
      : 0;

  return (
    <div className="max-w-5xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-2">Cobro de Consulta en Caja</h1>
      <p className="text-gray-500 text-sm mb-6">
        Busque citas con estado "Pendiente de pago" para procesar el cobro.
      </p>

      {/* Buscador */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border p-6 mb-6">
        <form
          className="flex flex-col md:flex-row gap-3"
          onSubmit={handleSearch}
        >
          <div className="flex gap-2">
            <button
              className={`px-4 py-2 rounded-lg text-sm font-semibold border transition-colors ${searchType === "dpi" ? "bg-blue-600 text-white border-blue-600" : "bg-white text-gray-600 border-gray-300"}`}
              type="button"
              onClick={() => setSearchType("dpi")}
            >
              Por DPI
            </button>
            <button
              className={`px-4 py-2 rounded-lg text-sm font-semibold border transition-colors ${searchType === "id" ? "bg-blue-600 text-white border-blue-600" : "bg-white text-gray-600 border-gray-300"}`}
              type="button"
              onClick={() => setSearchType("id")}
            >
              Por No. Cita
            </button>
          </div>
          <input
            className="flex-1 px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            placeholder={
              searchType === "dpi"
                ? "DPI del paciente (13 d├¡gitos)"
                : "N├║mero de cita"
            }
            type="text"
            value={searchValue}
            onChange={(e) => setSearchValue(e.target.value)}
          />
          <Button className="px-6" type="submit" variant="primary">
            <i className="bi bi-search mr-2" /> Buscar
          </Button>
        </form>
      </div>

      {isLoading ? <LoadingComponent /> : null}

      {/* Lista de citas pendientes */}
      {!isLoading && appointments.length > 0 && !selectedAppointment && (
        <div className="space-y-3 mb-6">
          <h2 className="font-bold text-lg">Citas Pendientes de Pago</h2>
          {appointments.map((appointment) => (
            <div
              key={appointment.id}
              className="border rounded-xl p-4 bg-yellow-50 border-yellow-200 cursor-pointer hover:bg-yellow-100 transition-colors"
              onClick={() => handleSelectAppointment(appointment)}
            >
              <div className="flex justify-between items-center">
                <div>
                  <p className="font-bold">
                    {appointment.patient?.name ??
                      `Paciente #${appointment.patientId}`}
                  </p>
                  <p className="text-sm text-gray-600">
                    Cita #{appointment.id} ┬À {appointment.specialty?.name} ┬À{" "}
                    {appointment.appointmentDate}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold text-green-700">
                    Q{appointment.amount?.toFixed(2)}
                  </p>
                  <Button size="sm" variant="primary">
                    Cobrar
                  </Button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {!isLoading && searchQuery && appointments.length === 0 ? (
        <div className="text-center py-8 text-gray-400">
          <i className="bi bi-cash-coin text-4xl block mb-3" />
          <p>
            No se encontraron citas pendientes de pago para los datos
            ingresados. Verifique el DPI o n├║mero de cita e intente de nuevo.
          </p>
        </div>
      ) : null}

