                >
                  <Label className="font-bold">Correo Electr├│nico *</Label>
                  <Input
                    className="px-3 py-2 border rounded-md"
                    placeholder="usuario@dominio.com"
                    type="email"
                    value={form.email}
                  />
                  {errors?.email ? (
                    <FieldError>{errors.email as string}</FieldError>
                  ) : null}
                </TextField>

                <TextField
                  isRequired
                  className="flex flex-col gap-1"
                  isInvalid={!!errors?.userName}
                  name="userName"
                  onChange={handleTextChange("userName")}
                >
                  <Label className="font-bold">
                    Nombre de Usuario * (8-9 chars)
                  </Label>
                  <Input
                    className="px-3 py-2 border rounded-md"
                    maxLength={9}
                    minLength={8}
                    placeholder="miusuario"
                    type="text"
                    value={form.userName}
                  />
                  {errors?.userName ? (
                    <FieldError>{errors.userName as string}</FieldError>
                  ) : null}
                </TextField>

                <TextField
                  isRequired
                  className="flex flex-col gap-1"
                  isInvalid={!!errors?.password}
                  name="password"
                  onChange={handleTextChange("password")}
                >
                  <Label className="font-bold">
                    Contrase├▒a * (m├¡n. 12 chars)
                  </Label>
                  <Input
                    className="px-3 py-2 border rounded-md"
                    placeholder="M├¡nimo 12 caracteres"
                    type="password"
                    value={form.password}
                  />
                  {errors?.password ? (
                    <FieldError>{errors.password as string}</FieldError>
                  ) : null}
                </TextField>

                <TextField
                  className="flex flex-col gap-1"
                  isInvalid={!!errors?.nit}
                  name="nit"
                  onChange={handleTextChange("nit")}
                >
                  <Label className="font-bold">NIT (8-9 chars, opcional)</Label>
                  <Input
                    className="px-3 py-2 border rounded-md"
                    placeholder="12345678"
                    type="text"
                    value={form.nit || ""}
                  />
                  {errors?.nit ? (
                    <FieldError>{errors.nit as string}</FieldError>
                  ) : null}
                </TextField>

                <TextField
                  className="flex flex-col gap-1"
                  isInvalid={!!errors?.insuranceNumber}
                  name="insuranceNumber"
                  onChange={handleTextChange("insuranceNumber")}
                >
                  <Label className="font-bold">
                    No. Seguro M├®dico (opcional)
                  </Label>
                  <Input
                    className="px-3 py-2 border rounded-md"
                    placeholder="N├║mero de afiliado"
                    type="text"
                    value={form.insuranceNumber || ""}
                  />
                  {errors?.insuranceNumber ? (
                    <FieldError>{errors.insuranceNumber as string}</FieldError>
                  ) : null}
                </TextField>
              </div>

              <AsyncButton
                className="py-3 mt-2 font-bold w-full"
                isLoading={loading}
                loadingText="Registrando..."
                size="lg"
                type="submit"
                variant="primary"
              >
                <i className="bi bi-person-plus mr-2" /> Registrarse
              </AsyncButton>
            </Form>

            <div className="flex flex-col items-center mt-4 gap-2 text-sm">
              <span className="text-gray-500">┬┐Ya tiene cuenta?</span>
              <button
                className="font-bold underline text-cyan-500"
                type="button"
                onClick={() => navigate("/auth")}
              >
                Iniciar Sesi├│n
              </button>
            </div>
          </div>
        </Card>
      </div>
    </section>
  );
}

export function Component() {
  return <RegisterPage />;
